'use client';
import { useMemo, useState } from 'react';
import type { LetterJumpConfig } from './LetterJumpGame';
interface Props { initialConfig?: LetterJumpConfig; onSave: (config: LetterJumpConfig) => void }
const DEFAULT_ITEMS=['A','B','C','D','E','F'];
export default function LetterJumpBuilder({initialConfig,onSave}:Props){const[title,setTitle]=useState(initialConfig?.title||'Alphabet Craft'),[instruction,setInstruction]=useState(initialConfig?.instruction||'Прыгни на правильную платформу'),[raw,setRaw]=useState((initialConfig?.items||DEFAULT_ITEMS).join('\n')),[rounds,setRounds]=useState(initialConfig?.rounds||8);const items=useMemo(()=>[...new Set(raw.split(/[\n,;]/).map(v=>v.trim()).filter(Boolean))],[raw]),valid=items.length>=3;return <div className="h-full overflow-y-auto bg-gradient-to-br from-sky-100 to-emerald-100 p-4"><div className="mx-auto max-w-3xl rounded-3xl bg-white p-6 shadow-xl"><h2 className="text-3xl font-black text-slate-800">⛏️ Конструктор Letter Jump</h2><p className="mt-1 text-sm text-slate-500">Введите минимум 3 буквы или слова. В каждом раунде игрок выбирает одну из трёх платформ.</p><div className="mt-5 grid gap-4 md:grid-cols-2"><label className="font-bold">Название<input value={title} onChange={e=>setTitle(e.target.value)} className="mt-1 w-full rounded-xl border-2 px-3 py-2"/></label><label className="font-bold">Инструкция<input value={instruction} onChange={e=>setInstruction(e.target.value)} className="mt-1 w-full rounded-xl border-2 px-3 py-2"/></label></div><label className="mt-4 block font-bold">Буквы или слова<textarea value={raw} onChange={e=>setRaw(e.target.value)} rows={9} className="mt-1 w-full rounded-xl border-2 px-3 py-2"/></label><div className={`mt-2 text-sm font-bold ${valid?'text-emerald-600':'text-red-600'}`}>Уникальных вариантов: {items.length} {valid?'✓':'(нужно минимум 3)'}</div><label className="mt-5 block font-bold">Раундов: {rounds}<input type="range" min={1} max={30} value={rounds} onChange={e=>setRounds(Number(e.target.value))} className="mt-2 w-full"/></label><button disabled={!valid} onClick={()=>onSave({title:title.trim()||'Alphabet Craft',instruction:instruction.trim(),items,rounds,lives:initialConfig?.lives||3})} className="mt-6 w-full rounded-xl bg-gradient-to-r from-emerald-600 to-green-800 px-5 py-3 text-lg font-black text-white disabled:opacity-40">Сохранить Letter Jump</button></div></div>}
