'use client';

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useAuth } from '../../../contexts/AuthContext';

export interface SpotlightActivityProps {
  isTeacher?: boolean;
  lessonId?: string;
  groupId?: number;
  activityId?: string;
  sessionId?: string;
  socket?: any;
  isConnected?: boolean;
}

interface SpotlightIframeActivityProps extends SpotlightActivityProps {
  src: string;
  title: string;
  doneMessageTypes?: string[];
  width?: number;
  height?: number;
  sandbox?: string;
}

export default function SpotlightIframeActivity({
  src,
  title,
  doneMessageTypes = ['spotlight-result'],
  width,
  height,
  sandbox,
  isTeacher,
  lessonId,
  groupId,
  activityId,
  sessionId,
  socket,
  isConnected,
}: SpotlightIframeActivityProps) {
  const { user } = useAuth();
  const containerRef = useRef<HTMLDivElement>(null);
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const [scale, setScale] = useState(1);
  const [submitted, setSubmitted] = useState(false);
  const messageTypes = useMemo(() => new Set(doneMessageTypes), [doneMessageTypes]);
  const resolvedSrc = useMemo(() => {
    const roleParam = isTeacher ? 'teacher=1' : 'student=1';
    const separator = src.includes('?') ? '&' : '?';
    return `${src}${separator}${roleParam}`;
  }, [isTeacher, src]);

  useEffect(() => {
    if (!width || !height) return;
    const el = containerRef.current;
    if (!el) return;

    const ro = new ResizeObserver(([entry]) => {
      const { width: currentWidth, height: currentHeight } = entry.contentRect;
      setScale(Math.min(currentWidth / width, currentHeight / height) * 0.98);
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, [width, height]);

  const handleMessage = useCallback(async (event: MessageEvent) => {
    const data = event.data;
    if (!data || typeof data !== 'object') return;

    const relayFromThisRole =
      ['lesson:card-opened', 'lesson:cards-reset', 'lesson:audio-play', 'lesson:audio-stop'].includes(data.type) ||
      (isTeacher && data.type === 'lesson:score-update');

    if (
      relayFromThisRole &&
      socket &&
      isConnected &&
      groupId != null &&
      data.type
    ) {
      socket.emit('spotlight-live-message', {
        ...data,
        lessonId,
        groupId,
        activityId,
        sessionId,
      });
      return;
    }

    if (!messageTypes.has(data.type)) return;
    if (submitted || isTeacher || !lessonId) return;

    const payloadResults = data.results ?? data.result ?? data.allResults ?? data;
    const normalizedTotal = Number(
      data.total ??
      data.totalItems ??
      (Array.isArray(payloadResults) ? payloadResults.length : 1)
    );

    try {
      await fetch('/kids-api/spotlight/results', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          lessonId,
          activityId,
          sessionId: sessionId || null,
          studentId: user?.id,
          studentName: user?.displayName || 'Ученик',
          results: payloadResults,
          score: Number(data.score ?? 0),
          total: Number.isFinite(normalizedTotal) && normalizedTotal > 0 ? normalizedTotal : 1,
        }),
      });
      setSubmitted(true);
    } catch {
      // Keep the activity playable if result submission fails.
    }
  }, [activityId, groupId, isConnected, isTeacher, lessonId, messageTypes, sessionId, socket, submitted, user]);

  useEffect(() => {
    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, [handleMessage]);

  useEffect(() => {
    const frameWindow = iframeRef.current?.contentWindow;
    if (!frameWindow) return;
    frameWindow.postMessage({
      type: 'set-role',
      role: isTeacher ? 'teacher' : 'student',
      lessonId,
      activityId,
      sessionId,
    }, '*');
  }, [activityId, isTeacher, lessonId, sessionId]);

  useEffect(() => {
    if (!socket || !isConnected) return;

    const handleLiveMessage = (data: any) => {
      if (activityId && data.activityId && data.activityId !== activityId) return;
      iframeRef.current?.contentWindow?.postMessage({
        ...data,
      }, '*');
    };

    socket.on('spotlight-live-message', handleLiveMessage);
    return () => {
      socket.off('spotlight-live-message', handleLiveMessage);
    };
  }, [activityId, isConnected, socket]);

  const handleIframeLoad = () => {
    iframeRef.current?.contentWindow?.postMessage({
      type: 'set-role',
      role: isTeacher ? 'teacher' : 'student',
      lessonId,
      activityId,
      sessionId,
    }, '*');
  };

  const iframe = (
    <iframe
      ref={iframeRef}
      src={resolvedSrc}
      title={title}
      width={width}
      height={height}
      className={!width || !height ? 'w-full h-full border-0' : undefined}
      style={width && height ? { border: 'none', display: 'block' } : undefined}
      scrolling="no"
      sandbox={sandbox}
      onLoad={handleIframeLoad}
    />
  );

  return (
    <div
      ref={containerRef}
      style={{
        width: '100%',
        height: '100%',
        overflow: 'hidden',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        background: '#f1f1f1',
        position: 'relative',
      }}
    >
      {width && height ? (
        <div style={{ width, height, transform: `scale(${scale})`, transformOrigin: 'center center', flexShrink: 0 }}>
          {iframe}
        </div>
      ) : iframe}
      {submitted && (
        <span style={{ position: 'absolute', bottom: 6, right: 10, fontSize: 11, color: '#16a34a', fontFamily: 'Arial,sans-serif' }}>
          ✔ результат сохранён
        </span>
      )}
    </div>
  );
}
