'use client';
import { useEffect, useRef, useState } from 'react';
type Point={x:number;y:number}; type Stroke={id:string;color:string;width:number;points:Point[];erase?:boolean};
interface Props{socket:any;isConnected:boolean;isTeacher:boolean;sessionId:string;groupId?:number}
export default function LiveDrawingOverlay({socket,isConnected,isTeacher,sessionId,groupId}:Props){
 const[enabled,setEnabled]=useState(false),[color,setColor]=useState('#ef4444'),[width,setWidth]=useState(5),[eraser,setEraser]=useState(false),[strokes,setStrokes]=useState<Stroke[]>([]);const current=useRef<Stroke|null>(null),strokesRef=useRef<Stroke[]>([]);strokesRef.current=strokes;
 useEffect(()=>{if(!socket||!isConnected)return;const draw=(d:any)=>{if(d?.sessionId!==sessionId)return;if(d.action==='stroke'&&d.stroke)setStrokes(p=>[...p.filter(s=>s.id!==d.stroke.id),d.stroke]);if(d.action==='clear')setStrokes([]);if(d.action==='state'&&Array.isArray(d.strokes))setStrokes(d.strokes)};const request=(d:any)=>{if(isTeacher&&d?.sessionId===sessionId)socket.emit('whiteboard-draw',{action:'state',strokes:strokesRef.current,sessionId,groupId})};socket.on('whiteboard-draw',draw);socket.on('whiteboard-request',request);if(!isTeacher)socket.emit('whiteboard-request',{sessionId,groupId});return()=>{socket.off('whiteboard-draw',draw);socket.off('whiteboard-request',request)}},[socket,isConnected,isTeacher,sessionId,groupId]);
 const point=(e:React.PointerEvent<SVGSVGElement>)=>{const r=e.currentTarget.getBoundingClientRect();return{x:Math.max(0,Math.min(1000,(e.clientX-r.left)/r.width*1000)),y:Math.max(0,Math.min(1000,(e.clientY-r.top)/r.height*1000))}};
 const start=(e:React.PointerEvent<SVGSVGElement>)=>{if(!isTeacher||!enabled)return;e.currentTarget.setPointerCapture(e.pointerId);const s:Stroke={id:`${Date.now()}-${Math.random()}`,color,width:eraser?30:width,points:[point(e)],erase:eraser};current.current=s;setStrokes(p=>[...p,s])};
 const move=(e:React.PointerEvent<SVGSVGElement>)=>{if(!current.current)return;const s={...current.current,points:[...current.current.points,point(e)]};current.current=s;setStrokes(p=>p.map(x=>x.id===s.id?s:x))};
 const end=()=>{if(!current.current)return;socket?.emit('whiteboard-draw',{action:'stroke',stroke:current.current,sessionId,groupId});current.current=null};const clear=()=>{setStrokes([]);socket?.emit('whiteboard-draw',{action:'clear',sessionId,groupId})};const path=(p:Point[])=>p.map((v,i)=>`${i?'L':'M'}${v.x.toFixed(1)},${v.y.toFixed(1)}`).join(' ');
 return <div className="pointer-events-none absolute inset-0 z-[70] overflow-hidden rounded-2xl"><svg viewBox="0 0 1000 1000" preserveAspectRatio="none" className={`absolute inset-0 h-full w-full touch-none ${isTeacher&&enabled?'pointer-events-auto cursor-crosshair':'pointer-events-none'}`} onPointerDown={start} onPointerMove={move} onPointerUp={end} onPointerCancel={end}><defs><mask id={`drawing-mask-${sessionId}`}><rect width="1000" height="1000" fill="white"/>{strokes.filter(s=>s.erase).map(s=><path key={s.id} d={path(s.points)} fill="none" stroke="black" strokeWidth={s.width} strokeLinecap="round" strokeLinejoin="round"/>)}</mask></defs><g mask={`url(#drawing-mask-${sessionId})`}>{strokes.filter(s=>!s.erase).map(s=><path key={s.id} d={path(s.points)} fill="none" stroke={s.color} strokeWidth={s.width} strokeLinecap="round" strokeLinejoin="round" vectorEffect="non-scaling-stroke"/>)}</g></svg>{isTeacher&&<div className="pointer-events-auto absolute right-2 top-2 flex items-center gap-1 rounded-full border bg-white/95 p-1.5 text-slate-800 shadow-xl"><button aria-label="Карандаш" title="Карандаш" onClick={()=>setEnabled(v=>!v)} className={`grid h-10 w-10 place-items-center rounded-full text-xl transition ${enabled?'bg-amber-400 shadow-inner':'bg-slate-100 hover:bg-slate-200'}`}>✏️</button>{enabled&&<><input aria-label="Цвет" title="Цвет" type="color" value={color} onChange={e=>{setColor(e.target.value);setEraser(false)}} className="h-9 w-9 rounded-full"/><input aria-label="Толщина" title="Толщина" type="range" min="2" max="14" value={width} onChange={e=>setWidth(Number(e.target.value))} className="w-20"/><button aria-label="Ластик" title="Ластик" onClick={()=>setEraser(v=>!v)} className={`grid h-9 w-9 place-items-center rounded-full ${eraser?'bg-blue-300':'bg-slate-100'}`}>🧽</button><button aria-label="Очистить" title="Очистить" onClick={clear} className="grid h-9 w-9 place-items-center rounded-full bg-rose-100">🗑️</button></>}</div>}</div>
}
