import { useState, useEffect, useRef } from 'react';
import type { Activity } from '../../../types';
import { useAuth } from '../../../contexts/AuthContext';
import { useActivityResult } from '../../../hooks/useActivityResult';

interface WordwallActivityRendererProps {
  activity: Activity;
  isViewMode: boolean;
  isTeacher: boolean;
  lessonId?: string;
  groupId?: number;
  sessionId?: string;
  onEdit: (activity: Activity) => void;
}

const WordwallActivityRenderer = ({
  activity,
  isViewMode,
  isTeacher,
  lessonId,
  groupId,
  sessionId,
  onEdit,
}: WordwallActivityRendererProps) => {
  const activityData = activity as any;
  const savedUrl: string = activityData.wordwallUrl || activityData.embedHtml || activityData.contentData?.wordwallUrl || '';
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const { user } = useAuth();
  const submitActivityResult = useActivityResult({
    activityId: activity.id!, lessonId, groupId, sessionId, isTeacher,
  });

  const [inputUrl, setInputUrl] = useState(savedUrl);
  const [previewUrl, setPreviewUrl] = useState(savedUrl);

  useEffect(() => {
    setInputUrl(savedUrl);
    setPreviewUrl(savedUrl);
  }, [activity.id]);

  useEffect(() => {
    if (!previewUrl.includes('/games/hsk3-lesson1.html')) return;
    const receiveResult = async (event: MessageEvent) => {
      if (event.origin !== window.location.origin || event.source !== iframeRef.current?.contentWindow) return;
      const data = event.data;
      if (!data || data.type !== 'hsk-stage-result' || !Array.isArray(data.answers)) return;

      const results = {
        source: data.source || 'hsk3',
        stage: data.stage,
        title: data.title || activity.title,
        action: data.action,
        feedback: data.feedback || '',
        answers: data.answers,
      };
      const score = Number(data.score) || 0;
      const total = Number(data.total) || 0;

      if (!isTeacher) {
        await submitActivityResult({
          score,
          status: 'completed',
          details: results,
        });
      }

      if (lessonId && user) {
        try {
          const response = await fetch('/kids-api/spotlight/results', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              lessonId,
              activityId: activity.id,
              sessionId: sessionId || null,
              studentId: (user as any).id || null,
              studentName: `${(user as any).displayName || (user as any).username || (isTeacher ? 'Учитель' : 'Ученик')}${isTeacher ? ' (учитель)' : ''}`,
              results: { ...results, participantRole: isTeacher ? 'teacher' : 'student' },
              score,
              total,
            }),
          });
          if (!response.ok) throw new Error(`HSK result API ${response.status}`);
        } catch (error) {
          console.error('[HSK] Failed to save stage answers:', error);
        }
      }
    };
    window.addEventListener('message', receiveResult);
    return () => window.removeEventListener('message', receiveResult);
  }, [activity.id, groupId, isTeacher, lessonId, previewUrl, sessionId, submitActivityResult, user]);

  const toEmbedUrl = (raw: string) => {
    const trimmed = raw.trim();
    if (trimmed.includes('<iframe')) {
      const m = trimmed.match(/src="([^"]+)"/);
      return m ? m[1] : '';
    }
    // wordwall.net/resource/XXX → wordwall.net/embed/XXX
    return trimmed.replace('wordwall.net/resource/', 'wordwall.net/embed/');
  };

  const handleApply = () => {
    const embed = toEmbedUrl(inputUrl);
    setPreviewUrl(embed);
    onEdit({
      ...activity,
      wordwallUrl: embed,
      contentData: { ...(activityData.contentData || {}), wordwallUrl: embed },
    } as any);
  };

  // Student / view-only mode — just show the iframe
  if (isViewMode || !isTeacher) {
    if (!previewUrl) {
      return (
        <div className="flex items-center justify-center h-full text-gray-400 text-lg">
          Ссылка на Wordwall не добавлена
        </div>
      );
    }
    return (
      <div className="w-full h-full">
        <iframe
          ref={iframeRef}
          src={previewUrl}
          className="w-full h-full border-0"
          title={activity.title}
          allow="autoplay; fullscreen; local-network-access *; local-network *; loopback-network *"
          allowFullScreen
        />
      </div>
    );
  }

  // Teacher edit mode — always show URL input + preview
  return (
    <div className="flex flex-col h-full">
      {/* URL input bar */}
      <div className="flex items-center gap-2 p-3 bg-gray-50 border-b border-gray-200 shrink-0">
        <span className="text-sm text-gray-500 shrink-0">🎮 Wordwall URL:</span>
        <input
          type="text"
          value={inputUrl}
          onChange={e => setInputUrl(e.target.value)}
          onKeyDown={e => { if (e.key === 'Enter') handleApply(); }}
          placeholder="Вставьте ссылку wordwall.net..."
          className="flex-1 px-3 py-1.5 border border-gray-300 rounded-lg text-sm focus:outline-none focus:border-purple-400"
        />
        <button
          onClick={handleApply}
          className="px-4 py-1.5 bg-purple-600 hover:bg-purple-700 text-white text-sm font-semibold rounded-lg transition shrink-0"
        >
          Применить
        </button>
      </div>

      {/* Preview */}
      <div className="flex-1 min-h-0">
        {previewUrl ? (
          <iframe
            ref={iframeRef}
            src={previewUrl}
            className="w-full h-full border-0"
            title={activity.title}
            allow="autoplay; fullscreen; local-network-access *; local-network *; loopback-network *"
            allowFullScreen
          />
        ) : (
          <div className="flex items-center justify-center h-full text-gray-400 flex-col gap-2">
            <span className="text-5xl">🎮</span>
            <span className="text-sm">Вставьте ссылку и нажмите «Применить»</span>
          </div>
        )}
      </div>
    </div>
  );
};

export default WordwallActivityRenderer;
