'use client';
import { useEffect, useRef, useState } from 'react';
type Point={x:number;y:number}; type Stroke={id:string;color:string;width:number;points:Point[];erase?:boolean};
interface Props{socket:any;isConnected:boolean;isTeacher:boolean;sessionId:string;groupId?:number}
export default function LiveTeachingBoard({socket,isConnected,isTeacher,sessionId,groupId}:Props){
 const[open,setOpen]=useState(false),[color,setColor]=useState('#2563eb'),[width,setWidth]=useState(5),[eraser,setEraser]=useState(false),[strokes,setStrokes]=useState<Stroke[]>([]);const current=useRef<Stroke|null>(null),stateRef=useRef({open:false,strokes:[] as Stroke[]});stateRef.current={open,strokes};
 const emit=(data:any)=>socket?.emit('teaching-board',{...data,sessionId,groupId});
 useEffect(()=>{if(!socket||!isConnected)return;const update=(d:any)=>{if(d?.sessionId!==sessionId)return;if(d.action==='visibility')setOpen(!!d.open);if(d.action==='stroke'&&d.stroke)setStrokes(p=>[...p.filter(s=>s.id!==d.stroke.id),d.stroke]);if(d.action==='clear')setStrokes([]);if(d.action==='state'){setOpen(!!d.open);if(Array.isArray(d.strokes))setStrokes(d.strokes)}};const request=(d:any)=>{if(isTeacher&&d?.sessionId===sessionId)emit({action:'state',...stateRef.current})};socket.on('teaching-board',update);socket.on('teaching-board-request',request);if(!isTeacher)socket.emit('teaching-board-request',{sessionId,groupId});return()=>{socket.off('teaching-board',update);socket.off('teaching-board-request',request)}},[socket,isConnected,isTeacher,sessionId,groupId]);
 const toggle=()=>{const next=!open;setOpen(next);emit({action:'visibility',open:next})};const point=(e:React.PointerEvent<SVGSVGElement>)=>{const r=e.currentTarget.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width*1000,y:(e.clientY-r.top)/r.height*1000}};
 const start=(e:React.PointerEvent<SVGSVGElement>)=>{if(!isTeacher)return;e.currentTarget.setPointerCapture(e.pointerId);const s:Stroke={id:`b-${Date.now()}-${Math.random()}`,color,width:eraser?35:width,erase:eraser,points:[point(e)]};current.current=s;setStrokes(p=>[...p,s])};const move=(e:React.PointerEvent<SVGSVGElement>)=>{if(!current.current)return;const s={...current.current,points:[...current.current.points,point(e)]};current.current=s;setStrokes(p=>p.map(x=>x.id===s.id?s:x))};const end=()=>{if(!current.current)return;emit({action:'stroke',stroke:current.current});current.current=null};const clear=()=>{setStrokes([]);emit({action:'clear'})};const path=(p:Point[])=>p.map((v,i)=>`${i?'L':'M'}${v.x.toFixed(1)},${v.y.toFixed(1)}`).join(' ');
 return <div className="pointer-events-none absolute inset-0 z-[90] overflow-hidden rounded-2xl">{isTeacher&&!open&&<button aria-label="Доска" title="Доска" onClick={toggle} className="pointer-events-auto absolute right-2 top-16 z-20 grid h-11 w-11 place-items-center rounded-full border bg-white text-xl text-slate-800 shadow-xl transition hover:bg-blue-50 hover:scale-105">📝</button>}<div className={`pointer-events-auto absolute inset-x-0 top-0 h-[85%] border-b-4 border-blue-300 bg-white shadow-2xl transition-transform duration-500 ease-out ${open?'translate-y-0':'-translate-y-[110%]'}`}>
   <div className="absolute inset-x-0 top-0 z-20 flex h-14 items-center justify-between gap-2 border-b bg-slate-100 px-3 text-slate-800"><strong className="text-lg">📝 Доска для объяснений</strong>{isTeacher&&<div className="flex items-center gap-1"><input aria-label="Цвет" type="color" value={color} onChange={e=>{setColor(e.target.value);setEraser(false)}} className="h-9 w-9"/><input aria-label="Толщина" type="range" min="2" max="16" value={width} onChange={e=>setWidth(Number(e.target.value))} className="w-20"/><button onClick={()=>setEraser(v=>!v)} className={`rounded-lg px-3 py-2 ${eraser?'bg-blue-300':'bg-white'}`}>🧽</button><button onClick={clear} className="rounded-lg bg-rose-100 px-3 py-2">🗑️</button><button onClick={toggle} className="rounded-lg bg-slate-700 px-3 py-2 font-bold text-white">Закрыть ↑</button></div>}</div>
   <div className="absolute inset-x-0 bottom-0 top-14 bg-white" style={{backgroundImage:'linear-gradient(#e5e7eb 1px,transparent 1px),linear-gradient(90deg,#e5e7eb 1px,transparent 1px)',backgroundSize:'28px 28px'}}><svg viewBox="0 0 1000 1000" preserveAspectRatio="none" className={`h-full w-full touch-none ${isTeacher?'cursor-crosshair':''}`} onPointerDown={start} onPointerMove={move} onPointerUp={end} onPointerCancel={end}><defs><mask id={`board-mask-${sessionId}`}><rect width="1000" height="1000" fill="white"/>{strokes.filter(s=>s.erase).map(s=><path key={s.id} d={path(s.points)} fill="none" stroke="black" strokeWidth={s.width} strokeLinecap="round" strokeLinejoin="round"/>)}</mask></defs><g mask={`url(#board-mask-${sessionId})`}>{strokes.filter(s=>!s.erase).map(s=><path key={s.id} d={path(s.points)} fill="none" stroke={s.color} strokeWidth={s.width} strokeLinecap="round" strokeLinejoin="round" vectorEffect="non-scaling-stroke"/>)}</g></svg></div>
  </div></div>
}
