'use client';
import { useState, useEffect } from 'react';

interface Props {
  isTeacher?: boolean;
  lessonId?: string;
  activityId?: string;
  sessionId?: string;
}

const SLOTS = ['A', 'B', 'C', 'D', 'E'];
const CORRECT: Record<string, string> = { A: 'age', B: 'height', C: 'weight', D: 'facial features', E: 'hair' };

interface StudentResult {
  id: string;
  student_name: string;
  results: { answers: Record<string, string> };
  score: number;
  total: number;
}

export default function SpotlightEx31({ isTeacher, lessonId, activityId, sessionId }: Props) {
  const [results, setResults] = useState<StudentResult[]>([]);

  useEffect(() => {
    if (!isTeacher || !lessonId) return;
    const load = async () => {
      try {
        let url = `/kids-api/spotlight/results/${lessonId}?activityId=${activityId ?? ''}`;
        if (sessionId) url += `&sessionId=${sessionId}`;
        const res = await fetch(url);
        const data = await res.json();
        if (data.success) setResults(data.data);
      } catch {}
    };
    load();
    const t = setInterval(load, 5000);
    return () => clearInterval(t);
  }, [isTeacher, lessonId, activityId, sessionId]);

  const params = new URLSearchParams();
  if (lessonId) params.set('lessonId', lessonId);
  if (activityId) params.set('activityId', activityId);
  if (sessionId) params.set('sessionId', sessionId);
  if (sessionId) params.set('role', isTeacher ? 'teacher' : 'student');
  const src = `/spotlight/ex31.html${params.toString() ? '?' + params.toString() : ''}`;

  return (
    <div style={{ width: '100%', height: '100%', display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
      <div style={{ flex: 1, overflow: 'hidden', minHeight: 0 }}>
        <iframe src={src} style={{ width: '100%', height: '100%', border: 'none', display: 'block' }} scrolling="no" />
      </div>

      {isTeacher && sessionId && (
        <div style={{ flexShrink: 0, maxHeight: 200, overflow: 'auto', borderTop: '2px solid #e0e0e0', background: '#fff' }}>
          {results.length === 0 ? (
            <div style={{ padding: '8px 16px', color: '#aaa', fontSize: 13 }}>Ожидание ответов учеников…</div>
          ) : (
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13 }}>
              <thead>
                <tr style={{ background: '#f5f5f5', position: 'sticky', top: 0 }}>
                  <th style={{ padding: '6px 12px', textAlign: 'left', borderBottom: '1px solid #e0e0e0' }}>Ученик</th>
                  {SLOTS.map(s => <th key={s} style={{ padding: '6px 10px', textAlign: 'center', borderBottom: '1px solid #e0e0e0' }}>{s}</th>)}
                  <th style={{ padding: '6px 10px', textAlign: 'center', borderBottom: '1px solid #e0e0e0' }}>Счёт</th>
                </tr>
              </thead>
              <tbody>
                {results.map(r => (
                  <tr key={r.id} style={{ borderBottom: '1px solid #f0f0f0' }}>
                    <td style={{ padding: '5px 12px', fontWeight: 500 }}>{r.student_name}</td>
                    {SLOTS.map(s => {
                      const ans = r.results?.answers?.[s];
                      const ok = ans === CORRECT[s];
                      return (
                        <td key={s} style={{ padding: '5px 10px', textAlign: 'center', fontSize: 12,
                          color: ans ? (ok ? '#4caf50' : '#e53935') : '#bbb', fontWeight: ans ? 700 : 400 }}>
                          {ans || '—'}
                        </td>
                      );
                    })}
                    <td style={{ padding: '5px 10px', textAlign: 'center', fontWeight: 700 }}>{r.score}/{r.total}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}
    </div>
  );
}
